import{_ as e,r as s,o,c,e as a,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const b=JSON.parse('{"title":"发送邮件 - October CMS - 3.x","titleTemplate":false,"description":"了解如何发送邮件和创建模板。","frontmatter":{"subtitle":"了解如何发送邮件和创建模板。"},"headers":[{"level":2,"title":"消息内容","slug":"消息内容","link":"#消息内容","children":[{"level":3,"title":"在后端面板中定义模板","slug":"在后端面板中定义模板","link":"#在后端面板中定义模板","children":[]},{"level":3,"title":"在后端面板中定义布局","slug":"在后端面板中定义布局","link":"#在后端面板中定义布局","children":[]},{"level":3,"title":"在文件系统中定义视图","slug":"在文件系统中定义视图","link":"#在文件系统中定义视图","children":[{"level":4,"title":"配置部分","slug":"配置部分","link":"#配置部分","children":[]}]},{"level":3,"title":"注册模板、布局和局部视图","slug":"注册模板、布局和局部视图","link":"#注册模板、布局和局部视图","children":[{"level":4,"title":"注册模板","slug":"注册模板","link":"#注册模板","children":[]},{"level":4,"title":"注册布局","slug":"注册布局","link":"#注册布局","children":[]},{"level":4,"title":"注册局部视图","slug":"注册局部视图","link":"#注册局部视图","children":[]},{"level":4,"title":"基于文件的布局","slug":"基于文件的布局","link":"#基于文件的布局","children":[]}]},{"level":3,"title":"全局变量","slug":"全局变量","link":"#全局变量","children":[]}]},{"level":2,"title":"发送邮件","slug":"发送邮件","link":"#发送邮件","children":[{"level":3,"title":"快速发送","slug":"快速发送","link":"#快速发送","children":[]},{"level":3,"title":"构建消息","slug":"构建消息","link":"#构建消息","children":[{"level":4,"title":"发送纯文本邮件","slug":"发送纯文本邮件","link":"#发送纯文本邮件","children":[]},{"level":4,"title":"发送解析的原始字符串","slug":"发送解析的原始字符串","link":"#发送解析的原始字符串","children":[]},{"level":4,"title":"发送原始字符串","slug":"发送原始字符串","link":"#发送原始字符串","children":[]}]},{"level":3,"title":"发送附件","slug":"发送附件","link":"#发送附件","children":[]},{"level":3,"title":"内联附件","slug":"内联附件","link":"#内联附件","children":[{"level":4,"title":"在邮件内容中嵌入图片","slug":"在邮件内容中嵌入图片","link":"#在邮件内容中嵌入图片","children":[]},{"level":4,"title":"在邮件内容中嵌入原始数据","slug":"在邮件内容中嵌入原始数据","link":"#在邮件内容中嵌入原始数据","children":[]}]}]},{"level":2,"title":"邮件队列","slug":"邮件队列","link":"#邮件队列","children":[{"level":3,"title":"将邮件消息排队","slug":"将邮件消息排队","link":"#将邮件消息排队","children":[]},{"level":3,"title":"延迟消息排队","slug":"延迟消息排队","link":"#延迟消息排队","children":[]},{"level":3,"title":"推送到特定队列","slug":"推送到特定队列","link":"#推送到特定队列","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}]}],"relativePath":"3.x/zh-cn/extend/system/sending-mail.md","filePath":"3.x/zh-cn/extend/system/sending-mail.md"}'),u={name:"3.x/zh-cn/extend/system/sending-mail.md"};function r(k,n,d,g,m,h){const t=s("pre-heading"),p=s("post-heading");return o(),c("div",null,[a(t),n[0]||(n[0]=l("h1",null,"发送邮件",-1)),a(p),n[1]||(n[1]=i(`<p>本文介绍如何构建邮件内容，包括使用布局和局部视图，以及发送邮件的方法。邮件内容支持基本的 Twig 标签和表达式。也支持 Markdown 语法，详情请参阅<a href="./../services/parser.html">在 Markdown 中使用 HTML</a> 部分。</p><h2 id="消息内容"><a href="#消息内容" class="header-anchor">#</a> 消息内容</h2><p>在 October CMS 中，可以使用邮件视图或邮件模板发送邮件消息。邮件视图由应用程序或插件在文件系统的 <strong>/views</strong> 目录中提供。而邮件模板则通过后端面板中的 <strong>设置 → 邮件模板</strong> 进行管理。</p><p>可选地，邮件视图可以在<a href="./../extending.html">插件注册文件</a>中使用 <code>registerMailTemplates</code> 方法进行注册。这会自动生成邮件模板的种子数据，允许使用后端面板进行自定义。</p><h3 id="在后端面板中定义模板"><a href="#在后端面板中定义模板" class="header-anchor">#</a> 在后端面板中定义模板</h3><p>你可以通过后端面板中的 <strong>设置 → 邮件模板</strong> 创建存储在数据库中的邮件模板。赋予模板的<strong>代码</strong>是唯一标识符，创建后不能更改。</p><p>例如，如果你创建了一个代码为 <code>my-template</code> 的模板，你可以使用以下 PHP 代码发送它：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;my-template&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><div class="custom-block tip"><p>如果系统中不存在邮件模板，此代码将尝试在文件系统中查找具有相同代码的邮件视图。</p></div><h3 id="在后端面板中定义布局"><a href="#在后端面板中定义布局" class="header-anchor">#</a> 在后端面板中定义布局</h3><p>可以通过选择 <strong>设置 → 邮件模板</strong> 并点击 <strong>布局</strong> 选项卡来创建邮件布局。它们的行为就像 CMS 布局一样，包含邮件消息的框架。邮件视图和模板支持使用邮件布局。</p><p>默认情况下，October CMS 提供两个默认邮件布局。</p><div class="table"><table tabindex="0"><thead><tr><th>布局</th><th>代码</th><th>描述</th></tr></thead><tbody><tr><td>默认</td><td><code>default</code></td><td>用于面向公众的前端邮件。</td></tr><tr><td>系统</td><td><code>system</code></td><td>用于内部后端邮件。</td></tr></tbody></table></div><h3 id="在文件系统中定义视图"><a href="#在文件系统中定义视图" class="header-anchor">#</a> 在文件系统中定义视图</h3><p>邮件视图位于文件系统中，使用的代码表示视图文件的路径。例如，使用代码 <code>author.plugin::mail.message</code> 发送邮件将使用以下文件中的内容。</p><pre class="dir-container"><code><p>├── plugins
|   └── author  <em>← &quot;author&quot; 段</em>
|       └── myplugin  <em>← &quot;plugin&quot; 段</em>
|           └── <code>views</code>
|               └── mail  <em>← &quot;mail&quot; 段</em>
|                   └── message.htm  <em>← &quot;message&quot; 段</em></p>
</code></pre><p>邮件视图文件中的内容最多可包含 3 个部分：<strong>配置</strong>、<strong>纯文本</strong>和 <strong>HTML 标记</strong>。各部分由 <code>==</code> 序列分隔。例如：</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

Good news! User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.

This message was sent using no formatting (plain text)
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>strong</span><span class="token punctuation">&gt;</span></span>Good news!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>strong</span><span class="token punctuation">&gt;</span></span>
    User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This email was sent using formatting (HTML)<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p><strong>纯文本</strong>部分是可选的，视图可以只包含<strong>配置</strong>和 <strong>HTML 标记</strong>部分。也支持 Markup 语法作为替代语法。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">default</span>&quot;</span>
<span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Hi <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>,

**Good news!** User <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> user <span class="token delimiter punctuation">}}</span></span> just added your product &quot;<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> product <span class="token delimiter punctuation">}}</span></span>&quot; to a project.
</code></pre></div></div><h4 id="配置部分"><a href="#配置部分" class="header-anchor">#</a> 配置部分</h4><p>配置部分设置邮件视图属性。支持以下配置属性。</p><div class="table"><table tabindex="0"><thead><tr><th>属性</th><th>描述</th></tr></thead><tbody><tr><td><strong>subject</strong></td><td>邮件消息主题，必填。</td></tr><tr><td><strong>layout</strong></td><td>邮件布局代码或视图，可选。默认值为 <code>default</code>。</td></tr></tbody></table></div><h3 id="注册模板、布局和局部视图"><a href="#注册模板、布局和局部视图" class="header-anchor">#</a> 注册模板、布局和局部视图</h3><div class="custom-block aside"><p>后端面板中的<strong>代码</strong>值将与邮件视图路径相同。例如，<code>author.plugin:mail.message</code>。</p></div><p>邮件视图可以注册为在后端面板中创建的默认模板。模板通过覆盖<a href="./../extending.html">插件注册文件</a>的 <code>registerMailTemplates</code> 方法进行注册。模板可以实现局部视图和布局，类似于 CMS 主题，它们分别使用 <code>registerMailLayouts</code> 和 <code>registerMailPartials</code> 进行注册。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Templates defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Layouts defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>

<span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token comment">// ...Partials defined here</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>在后端面板中，当生成的模板首次保存时，自定义内容将在发送分配代码的邮件时使用。在此上下文中，注册的邮件视图可以被视为默认或后备视图。</p><h4 id="注册模板"><a href="#注册模板" class="header-anchor">#</a> 注册模板</h4><p>注册数组中的 <code>templates</code> 键用于将视图注册为邮件模板。该方法应返回一个数组，其中键是模板代码，值是<a href="./../services/response-view.html">视图路径</a>的名称。模板代码用于引用模板。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailTemplates</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;rainlab.user:activate&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rainlab.user::mail.activate&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;rainlab.user:restore&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;rainlab.user::mail.restore&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>发送消息使用模板代码，例如。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;rainlab.user:activate&#39;</span><span class="token punctuation">,</span> <span class="token operator">...</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="注册布局"><a href="#注册布局" class="header-anchor">#</a> 注册布局</h4><p><code>registerMailLayouts</code> 方法覆盖用于注册布局，每个布局需要一个唯一的 <code>code</code> 来标识它，以及内容的默认视图文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailLayouts</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;marketing&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.marketing&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;notification&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::layouts.notification&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>现在可以在模板中使用 <code>code</code> 值引用布局。</p><div class="custom-block cmstemplate"><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">marketing</span>&quot;</span>
</code></pre></div><div class="language-twig extra-class"><pre class="language-twig"><code>Page contents...
</code></pre></div></div><h4 id="注册局部视图"><a href="#注册局部视图" class="header-anchor">#</a> 注册局部视图</h4><p>与布局类似，邮件局部视图可以使用 <code>registerMailPartials</code> 方法覆盖进行注册，每个局部视图需要一个唯一的 <code>code</code> 来标识它，以及内容的默认视图文件。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">registerMailPartials</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;tracking&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.tracking&#39;</span><span class="token punctuation">,</span>
        <span class="token string single-quoted-string">&#39;promotion&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog::partials.promotion&#39;</span><span class="token punctuation">,</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>现在可以在模板中使用 <code>{% partial %}</code> 标签和 <code>code</code> 值引用局部视图。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>tracking<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="基于文件的布局"><a href="#基于文件的布局" class="header-anchor">#</a> 基于文件的布局</h4><p>要引用基于文件的布局，你可以将视图代码传递给 <strong>layout</strong> 属性。例如，此邮件视图引用 <code>acme.blog::mail.custom-layout</code> 的布局。</p><div class="language-ini extra-class"><pre class="language-ini"><code><span class="token key attr-name">layout</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">acme.blog::mail.custom-layout</span>&quot;</span>
<span class="token key attr-name">subject</span> <span class="token punctuation">=</span> <span class="token value attr-value">&quot;<span class="token inner-value">Your product has been added to October CMS project</span>&quot;</span>
<span class="token punctuation">=</span><span class="token value attr-value">=</span>
...
</code></pre></div><p>使用上述代码，它将尝试从路径 <strong>plugins/acme/blog/views/mail/custom-layout.htm</strong> 加载布局内容，以下是内容示例。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>html</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h1</span><span class="token punctuation">&gt;</span></span>HTML Contents<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h1</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> content<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>html</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><div class="custom-block warning"><p>基于文件的布局内容不能在管理面板中编辑。</p></div><h3 id="全局变量"><a href="#全局变量" class="header-anchor">#</a> 全局变量</h3><p>你可以使用 <code>View::share</code> 方法注册所有邮件模板全局可用的变量。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此代码可以在<a href="./../plugin/registration.html">插件注册文件</a>的 register 或 boot 方法中调用。使用上面的示例，变量 <code>{{ site_name }}</code> 将在所有邮件模板中可用。</p><h2 id="发送邮件"><a href="#发送邮件" class="header-anchor">#</a> 发送邮件</h2><p>要发送消息，使用 <code>Mail</code> 门面上的 <code>send</code> 方法，该方法接受三个参数。第一个参数是用于定位邮件视图或邮件模板的唯一邮件代码。第二个参数是你希望传递给视图的数据数组。第三个参数是一个 <code>Closure</code> 回调，它接收消息实例，允许你自定义收件人、主题和邮件消息的其他方面。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// These variables are available inside the message as Twig</span>
<span class="token variable">$vars</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;name&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Joe&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;user&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Mary&#39;</span><span class="token punctuation">]</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;This is a reminder&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>由于我们在上面的示例中传递了一个包含 <code>name</code> 键的数组，我们可以在邮件视图中使用以下 Twig 标记显示该值。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> name <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><div class="custom-block warning"><p>你应避免在消息中传递 <code>message</code> 变量，此变量始终会传递，并允许内联嵌入附件。</p></div><h3 id="快速发送"><a href="#快速发送" class="header-anchor">#</a> 快速发送</h3><p>October CMS 还包含一个名为 <code>sendTo</code> 的替代方法，可以简化邮件发送。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token comment">// Send to address using no name</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send using an object&#39;s properties</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$user</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Send to multiple addresses</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Admin Person&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Alternatively send a raw message without parameters</span>
<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">rawTo</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;admin@domain.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;Hello friend&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p><code>sendTo</code> 中的第一个参数用于收件人，可以接受不同的值类型。</p><div class="table"><table tabindex="0"><thead><tr><th>类型</th><th>描述</th></tr></thead><tbody><tr><td>字符串</td><td>单个收件人地址，未定义名称。</td></tr><tr><td>数组</td><td>多个收件人，其中数组键是地址，值是名称。</td></tr><tr><td>对象</td><td>单个收件人对象，其中 <em>email</em> 属性用于地址，<em>name</em> 可选用于名称。</td></tr><tr><td>集合</td><td>收件人对象的集合，如上所述。</td></tr></tbody></table></div><p><code>sendTo</code> 的完整签名如下。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">sendTo</span><span class="token punctuation">(</span><span class="token variable">$recipient</span><span class="token punctuation">,</span> <span class="token variable">$message</span><span class="token punctuation">,</span> <span class="token variable">$params</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">,</span> <span class="token variable">$options</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><ul><li><code>$recipient</code> 如上所定义。</li><li><code>$message</code> 是模板名称或用于原始发送的消息内容。</li><li><code>$params</code> 在模板内部可用的变量数组。</li><li><code>$callback</code> 使用一个参数调用，即如 <code>send</code> 方法所述的消息构建器（可选，默认为 null）。如果不是可调用值，则作为下一个选项参数的替代。</li><li><code>$options</code> 作为数组传递的自定义发送选项（可选）</li></ul><p>支持以下自定义发送 <code>$options</code>。</p><div class="table"><table tabindex="0"><thead><tr><th>选项</th><th>描述</th></tr></thead><tbody><tr><td><strong>queue</strong></td><td>指定是将消息排队还是直接发送，可选。默认值：<code>false</code>。</td></tr><tr><td><strong>bcc</strong></td><td>指定是否将收件人添加为 Bcc 或常规 To 地址。默认值：<code>false</code>。</td></tr></tbody></table></div><h3 id="构建消息"><a href="#构建消息" class="header-anchor">#</a> 构建消息</h3><p>如前所述，传递给 <code>send</code> 方法的第三个参数是一个 <code>Closure</code>，允许你指定邮件消息本身的各种选项。使用此闭包，你可以指定消息的其他属性，如抄送、密送等：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span><span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;us@example.tld&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;foo@example.tld&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;bar@example.tld&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>以下是 <code>$message</code> 消息构建器实例上可用方法的列表。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">from</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">sender</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">to</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">cc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">bcc</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">replyTo</span><span class="token punctuation">(</span><span class="token variable">$address</span><span class="token punctuation">,</span> <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token constant">null</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">subject</span><span class="token punctuation">(</span><span class="token variable">$subject</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">priority</span><span class="token punctuation">(</span><span class="token variable">$level</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// Attach a file from a raw $data string...</span>
<span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attachData</span><span class="token punctuation">(</span><span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$name</span><span class="token punctuation">,</span> <span class="token keyword type-hint">array</span> <span class="token variable">$options</span> <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="发送纯文本邮件"><a href="#发送纯文本邮件" class="header-anchor">#</a> 发送纯文本邮件</h4><p>默认情况下，传递给 <code>send</code> 方法的视图被假定为包含邮件视图，你可以指定一个纯文本视图，除 HTML 视图外一并发送。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:message&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>或者，如果你只需要发送纯文本邮件，可以使用数组中的 <code>text</code> 键来指定：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;acme.blog:text&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token variable">$callback</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="发送解析的原始字符串"><a href="#发送解析的原始字符串" class="header-anchor">#</a> 发送解析的原始字符串</h4><p>如果你希望直接通过邮件发送原始字符串，可以使用 <code>raw</code> 方法。此内容将由 Markdown 解析。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Text to e-mail&#39;</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此外，此字符串将由 Twig 解析，如果你希望向此环境传递变量，请改用 <code>send</code> 方法，将内容作为 <code>raw</code> 键传递。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;raw&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;Text to email&#39;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token variable">$vars</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="发送原始字符串"><a href="#发送原始字符串" class="header-anchor">#</a> 发送原始字符串</h4><p>如果你传递一个包含 <code>text</code> 或 <code>html</code> 键的数组，这将是一个明确的发送邮件请求。不使用布局或 Markdown 解析。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">raw</span><span class="token punctuation">(</span><span class="token punctuation">[</span>
    <span class="token string single-quoted-string">&#39;text&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;This is plain text&#39;</span><span class="token punctuation">,</span>
    <span class="token string single-quoted-string">&#39;html&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;&lt;strong&gt;This is HTML&lt;/strong&gt;&#39;</span>
<span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="发送附件"><a href="#发送附件" class="header-anchor">#</a> 发送附件</h3><p>要向邮件添加附件，使用传递给闭包的 <code>$message</code> 对象上的 <code>attach</code> 方法。<code>attach</code> 方法接受文件的完整路径作为第一个参数：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">send</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>

    <span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>当向消息附加文件时，你还可以通过将 <code>array</code> 作为 <code>attach</code> 方法的第二个参数传递来指定显示名称和/或 MIME 类型：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$message</span><span class="token operator">-&gt;</span><span class="token function">attach</span><span class="token punctuation">(</span><span class="token variable">$pathToFile</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;as&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$display</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;mime&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$mime</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="内联附件"><a href="#内联附件" class="header-anchor">#</a> 内联附件</h3><h4 id="在邮件内容中嵌入图片"><a href="#在邮件内容中嵌入图片" class="header-anchor">#</a> 在邮件内容中嵌入图片</h4><p>将内联图片嵌入邮件通常很麻烦；但是，有一种便捷的方式可以将图片附加到邮件并获取适当的 CID。要嵌入内联图片，在邮件视图中使用 <code>message</code> 变量上的 <code>embed</code> 方法。请记住，<code>message</code> 变量在所有邮件视图中都可用：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>如果你计划使用队列邮件，请确保文件路径是绝对的。要实现这一点，你可以简单地使用 <a href="./../../markup/filter/app.html">app 过滤器</a>：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image:
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> pathToFile <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&#39;</span>storage/app/media/path/to/file.jpg<span class="token punctuation">&#39;</span></span><span class="token operator">|</span>app <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embed<span class="token punctuation">(</span>pathToFile<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h4 id="在邮件内容中嵌入原始数据"><a href="#在邮件内容中嵌入原始数据" class="header-anchor">#</a> 在邮件内容中嵌入原始数据</h4><p>如果你已有一个原始数据字符串希望嵌入邮件消息中，可以使用 <code>message</code> 变量上的 <code>embedData</code> 方法：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>body</span><span class="token punctuation">&gt;</span></span>
    Here is an image from raw data:

    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>img</span> <span class="token attr-name">src</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message<span class="token punctuation">.</span>embedData<span class="token punctuation">(</span>data<span class="token punctuation">,</span> name<span class="token punctuation">)</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="邮件队列"><a href="#邮件队列" class="header-anchor">#</a> 邮件队列</h2><h3 id="将邮件消息排队"><a href="#将邮件消息排队" class="header-anchor">#</a> 将邮件消息排队</h3><p>由于发送邮件消息可能会大幅延长应用程序的响应时间，许多开发者选择将消息排队以在后台发送。使用内置的<a href="./../services/queue.html">统一队列 API</a> 可以轻松实现。要将邮件消息排队，使用 <code>Mail</code> 门面上的 <code>queue</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queue</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>此方法将自动处理将作业推送到队列中以在后台发送邮件消息。当然，在使用此功能之前，你需要<a href="./../services/queue.html">配置队列</a>。</p><h3 id="延迟消息排队"><a href="#延迟消息排队" class="header-anchor">#</a> 延迟消息排队</h3><p>如果你希望延迟发送排队的邮件消息，可以使用 <code>later</code> 方法。要开始使用，只需将你希望延迟发送消息的秒数作为方法的第一个参数传递。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">later</span><span class="token punctuation">(</span><span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h3 id="推送到特定队列"><a href="#推送到特定队列" class="header-anchor">#</a> 推送到特定队列</h3><p>如果你希望指定将消息推送到哪个特定队列，可以使用 <code>queueOn</code> 和 <code>laterOn</code> 方法：</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">queueOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token class-name static-context">Mail</span><span class="token operator">::</span><span class="token function">laterOn</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;queue-name&#39;</span><span class="token punctuation">,</span> <span class="token number">5</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;acme.blog:welcome&#39;</span><span class="token punctuation">,</span> <span class="token variable">$data</span><span class="token punctuation">,</span> <span class="token keyword">function</span> <span class="token punctuation">(</span><span class="token variable">$message</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token comment">//</span>
<span class="token punctuation">}</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./../../setup/mail-config.html">邮件配置</a></li></ul></div>`,114))])}const f=e(u,[["render",r]]);export{b as __pageData,f as default};
